#!/bin/bash
go test ./conformance -count=1 -run TestConformance -v -timeout=3h -args  --gateway-class=kubvernor-conformance-gateway-envoy --conformance-profiles=GATEWAY-HTTP,GATEWAY-GRPC,GATEWAY-TLS --organization=kubvernor  --allow-crds-mismatch --project=kubvernor  --url=github.com/kubvernor/kubvernor --version=0.2.1  --contact=https://github.com/kubvernor/kubvernor/issues  --supported-features=Gateway,HTTPRoute,GatewayPort8080,HTTPRouteHostRewrite,HTTPRoutePathRedirect,HTTPRouteRequestMirror,HTTPRouteRequestPercentageMirror,HTTPRouteResponseHeaderModification,HTTPRouteSchemeRedirect,TLSRoute  --report-output=kubvernor-gateway-conformance-report-1.4.0-envoy.yaml
